@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

.product-info-resolved {
  animation: content-fade-in 0.4s ease;
}

@keyframes content-fade-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes slide-out-to-left {
  to {
    transform: translateX(-100%);
  }
}

@keyframes slide-in-from-right {
  from {
    transform: translateX(100%);
  }
}

@keyframes slide-out-to-right {
  to {
    transform: translateX(100%);
  }
}

@keyframes slide-in-from-left {
  from {
    transform: translateX(-100%);
  }
}

@keyframes fade-out {
  to {
    opacity: 0;
  }
}

@keyframes fade-in {
  from {
    opacity: 0;
  }
}

::view-transition-old(root) {
  animation: fade-out 150ms ease,
    slide-out-to-left 300ms ease;
}

::view-transition-new(root) {
  animation: fade-in 150ms ease,
    slide-in-from-right 300ms ease;
}

:root[data-nav-direction="back"]::view-transition-old(root) {
  animation: fade-out 150ms ease,
    slide-out-to-right 300ms ease;
}

:root[data-nav-direction="back"]::view-transition-new(root) {
  animation: fade-in 150ms ease,
    slide-in-from-left 300ms ease;
}

::view-transition-old(product-image),
::view-transition-new(product-image) {
  width: 100%;
  height: 100%;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }

  ::view-transition-old(root),
  ::view-transition-new(root) {
    animation: none !important;
  }

  ::view-transition-group(root) {
    animation-duration: 0.25s;
  }
}

